from ta5g_dev_wro1.change_sw_config_params import ChangeSWConfigParams
from ta5g_dev_wro1.XMLTools import XMLTools

from ta5g_dev_wro1.get_cpu_address_for_tti_traces import GetCPUAddressForTTITraces
from ta5g_dev_wro1.tti_trace_common import TtiTraceCommon

# from resources.ta_dev_wro1.download_tlda_decoder import TldaDownloader


class ta5g_dev_wro1(object):
    def change_swconfig_params(self, swconfig_path, *params):
        """
        Method for change swconfig params.
        :param swconfig_path path to swconfig file.
        :param params list with patameters to change in swconfig as
               strings e.g. "0x1 = 0x15 #param1"; "0x2  =  0x5" string must contain '=' sign.
        """
        changer = ChangeSWConfigParams(swconfig_path)
        changer.change_params(*params)

    @staticmethod
    def check_if_flags_are_set(swconfig_path, *params):
        changer = ChangeSWConfigParams(swconfig_path)
        return changer.check_if_flags_are_set(*params)

    def change_mme_address(self, scfc_src, scfc_dst, new_ip):
        """
        Method for changing BTS hostname and MME IP in SCFC.xml
        :param scfc_src: Source SCFC file path
        :param scfc_dst: Destination SCFC file path
        :param bts_hostname: New BTS hostname
        :param new_ip: New MME IP
        :return: None
        """
        XMLTools().change_mme_address(scfc_src, scfc_dst, new_ip)

    def change_sw_version_in_iphy(self, iphy_src, iphy_dst, targetbd, change_sw_file_key=None):
        """
        Changes sw version according to targetBD.xml
        :param iphy_src: Source iphy.xml file path
        :param iphy_dst: Destination iphy.xml file path
        :param targetbd: targetBD.xml file path
        :return: None
        """
        XMLTools().change_iphy_xml(iphy_src, iphy_dst, targetbd, change_sw_file_key)

    def change_vlans_in_iphy_aic(self, iphy_src, iphy_dst):
        """
        Changes preferredVlanId according to __init__.py
        :param iphy_src: Source iphy.xml file path
        :param iphy_dst: Destination iphy.xml file path
        :return: None
        """
        XMLTools().change_vlanid_in_iphy_xml(iphy_src, iphy_dst)

