    def verify_scfc_object_parameter_value(self, scfc, distname_list, parameter_name, expected_value):
        """
        Checks if a parameter in specified object exists and has expected value.
        Doesn't work if parameter is inside a list.
        :param scfc: SCFC.xml file path
        :param distname_list: List with object path (distname)
        :param parameter_name:
        :param expected_value:
        :return: bool
        """
        return XMLTools().verify_scfc_object_parameter(scfc, distname_list, parameter_name, expected_value)

    def get_file_lines_from_tti_trace_txt_file(self, tti_txt_dirpath, tti_trace_direction):
        """
        Get list of every lines from DL.txt or UL.txt and every line is a list of column values
        :param tti_txt_dirpath: path to directory where DL.txt and UL.txt are stored
        :param tti_trace_direction: string 'dl' or 'ul'
        :return: returns list of lines and every line is list of values
        """
        return TtiTraceCommon().get_file_lines_from_tti_trace_txt_file(tti_txt_dirpath, tti_trace_direction)

    def filter_tti_trace_by_value_different_than_requested_value_in_given_column(
        self, tti_file_lines, column_name, value
    ):
        """
        Remove lines that match value/values under related column - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value or list of values under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='not in'
        )

    def filter_tti_trace_by_value_in_given_column(self, tti_file_lines, column_name, value):
        """
        Remove lines that not match value/values under related column - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value or list of values under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='in'
        )

    def filter_and_compare_tti_trace_value_in_given_column_with_parameter_list(
        self, tti_file_lines, column_name, value, parameter_list
    ):
        """
        Remove lines that not match value/values under related column and compare using specific
        condition with other values under different column. KW fails if comparison fails.
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value related column
        :parameter_list :  in format e.g. ['ETtiTraceUlParUe_tbsCw1 == 0','ETtiTraceUlParUe_Modulation == QPSK',]
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_and_compare_tti_trace_value_in_given_column_with_parameter_list(
            tti_file_lines, column_name, value, parameter_list
        )

    def filter_tti_trace_by_value_lower_than_requested_value_in_given_column(self, tti_file_lines, column_name, value):
        """
        Remove lines that value under related column is greater than give value - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='<'
        )

    def filter_tti_trace_by_value_greater_than_requested_value_in_given_column(
        self, tti_file_lines, column_name, value
    ):
        """
        Remove lines that value under related column is lover than give value - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='>'
        )

    def filter_tti_trace_by_value_greater_or_equal_to_requested_value_in_given_column(
        self, tti_file_lines, column_name, value
    ):
        """
        Remove lines that value under related column is lover or equal than give value - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='>='
        )

    def filter_tti_trace_by_value_lower_or_equal_to_requested_value_in_given_column(
        self, tti_file_lines, column_name, value
    ):
        """
        Remove lines that value under related column is greater or equal than give value - return rest
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :param value: string - value under related column
        :return: list of lines and every line is list of values
        """
        return TtiTraceCommon().filter_tti_trace_by_value_in_given_column(
            tti_file_lines, column_name, value, condition='<='
        )

    def get_index_of_tti_column(self, tti_file_lines, column_name):
        """
        Get index of column name in TTI
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param column_name: string - column name from TTI
        :return: return index of given column name
        """
        return TtiTraceCommon().get_index_of_tti_column(tti_file_lines, column_name)

    def get_duration_from_tti_file_lines(self, tti_file_lines):
        """
        Get duration of TTI trace
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time in seconds in format e.g. 0.005
        """
        return TtiTraceCommon().get_duration_from_tti_file_lines(tti_file_lines)

    def get_time_from_tti_file_line(self, tti_file_line):
        """
        Get time (under Time column) from single TTI line in format e.g. 11:57:46.885
        :param tti_file_line: single tti file line - e.g. file_lines[4] where file_lines is
               return from get_file_lines_from_tti_trace_txt_file()
        :return: string - time (under Time column) from single TTI line in format e.g. 11:57:46.885
        """
        return TtiTraceCommon().get_time_from_tti_file_line(tti_file_line)

    def get_values_from_columns_in_tti(self, tti_file_lines, names_of_colums):
        """
        Get all values from specified columns names in TTI trace
        :param tti_file_lines: is return from get_file_lines_from_tti_trace_txt_file()
        :param names_of_colums: list of column names - one element list is OK
        :return: return same format as get_file_lines_from_tti_trace_txt_file() but only from specified column names
        """
        return TtiTraceCommon().get_values_from_columns_in_tti(tti_file_lines, names_of_colums)

    def get_cpu_address_for_tti_traces(self, cell, direction, is_nb_iot=0):
        """
        Gets CPU addresses needed for collecting TTI traces. Works for MACUL and MACDL deployment.
        :param cell: define cell number you are interested in getting deployment
        :param direction: define direction you need - downlink, uplink or both. Input one as a string.
        :param is_nb_iot: flag for NB-IoT. In NB-IoT TTI Traces are gathered from MACDLTTI sicad
        :return: returns board, DSP and core number of MAC PS. Needed as input for ttistream
        Sample usage: get_core_number_for_tti_traces(1, "uplink") gets DSP core for UL Scheduler of cell 1
        """
        return GetCPUAddressForTTITraces().get_cpu_address(cell, direction, is_nb_iot)

    def choose_cores_for_tti_trace_gathering_for_both_directions(self, cell_number=1, is_nb_iot=0):
        """
        Gets CPU addresses needed for collecting TTI traces. Works for MACUL and MACDL deployment.
        :param cell_number: defines a cell number (lncell id) you want to deploy
        :return: returns a board, a DSP and a core number of MAC PS as a dictionary
        Sample usage: choose_cores_for_tti_trace_gathering_for_both_directions(1) gets DSP core for DL & UL Scheduler of cell 1
        """
        if not isinstance(cell_number, list):
            cell_number = [cell_number]
        result = {}
        for cell in cell_number:
            cell = int(cell)
            tti_trace_core_num = self.get_cpu_address_for_tti_traces(cell, "both", is_nb_iot)
            result[cell] = tti_trace_core_num

        return result
